create extension if not exists pgtap with schema extensions;
begin;
select no_plan();
select ok(not pg_has_role('authenticated','atelier_planning_writer','MEMBER'),'authenticated cannot assume planning writer');
select ok(not pg_has_role('anon','atelier_planning_writer','MEMBER'),'anon cannot assume planning writer');
select ok(not has_function_privilege('authenticated','private.append_planning_revision(uuid,jsonb)','EXECUTE'),'authenticated cannot call writer');
select ok(not has_function_privilege('anon','private.append_planning_revision(uuid,jsonb)','EXECUTE'),'anon cannot call writer');
select ok(not has_function_privilege('authenticated','private.release_planning_request(uuid)','EXECUTE'),'client cannot release reservations');
select ok(has_function_privilege('atelier_planning_writer','private.append_planning_revision(uuid,jsonb)','EXECUTE'),'writer has narrow function access');
select ok(not has_table_privilege('atelier_planning_writer','public.product_revisions','INSERT'),'writer cannot insert revisions directly');
select ok(not has_table_privilege('authenticated','private.planning_requests','SELECT,INSERT,UPDATE,DELETE'),'client cannot access admission state');
select ok((select not rolcanlogin and not rolsuper and not rolcreaterole and not rolbypassrls from pg_roles where rolname='atelier_planning_writer'),'writer is unprivileged NOLOGIN role');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.proname in ('reserve_planning_request','append_planning_revision','release_planning_request') and p.prosecdef and p.proconfig @> array['search_path=""']),3::bigint,'all admission functions pin empty search path');
select ok(not exists(select 1 from pg_auth_members where member=(select oid from pg_roles where rolname='atelier_planning_writer')),'writer inherits no elevated roles');
select ok(not exists(select 1 from pg_proc p, lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.proname in ('append_planning_revision','release_planning_request','reserve_planning_request') and a.grantee=0 and a.privilege_type='EXECUTE'),'no PUBLIC function execution grants');
insert into auth.users(id,email) values('71000000-0000-4000-8000-000000000001','admission-owner@example.test');
insert into public.accounts(id,name,created_by) values('72000000-0000-4000-8000-000000000001','Admission account','71000000-0000-4000-8000-000000000001');
insert into public.account_memberships(account_id,user_id,role) values('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001','owner');
create temp table admission_fixture(k text primary key,v uuid);
grant all on admission_fixture to authenticated;
create function pg_temp.fixture(text) returns uuid language sql as 'select v from admission_fixture where k=$1';
set local role authenticated;
select set_config('request.jwt.claim.sub','71000000-0000-4000-8000-000000000001',true);
with p as(select * from public.create_product_with_revision('Admission one')) insert into admission_fixture select 'p1',product_id from p union all select 'r1',revision_id from p;
with p as(select * from public.create_product_with_revision('Admission two')) insert into admission_fixture select 'p2',product_id from p union all select 'r2',revision_id from p;
with p as(select * from public.create_product_with_revision('Admission three')) insert into admission_fixture select 'p3',product_id from p union all select 'r3',revision_id from p;
insert into admission_fixture values('token',public.reserve_planning_request(pg_temp.fixture('p1'),pg_temp.fixture('r1'),'first'));
select throws_ok($$select public.reserve_planning_request(pg_temp.fixture('p1'),pg_temp.fixture('r1'),'first')$$,'23505',null,'duplicate request rejected');
select throws_ok($$select public.reserve_planning_request(pg_temp.fixture('p1'),pg_temp.fixture('r1'),'parallel')$$,'53300',null,'one active request per product');
select lives_ok($$select public.reserve_planning_request(pg_temp.fixture('p2'),pg_temp.fixture('r2'),'second')$$,'second product fits owner concurrency limit');
select throws_ok($$select public.reserve_planning_request(pg_temp.fixture('p3'),pg_temp.fixture('r3'),'third')$$,'53300',null,'third active request exceeds owner limit');
reset role;
update private.planning_requests set expires_at=clock_timestamp()-interval '1 second' where id=pg_temp.fixture('token');
select throws_ok($$select * from private.append_planning_revision(pg_temp.fixture('token'),'{}')$$,'42501',null,'expired reservation cannot authorize a write');
set local role authenticated;
select throws_ok($$select public.reserve_planning_request(pg_temp.fixture('p1'),pg_temp.fixture('r1'),'first')$$,'23505',null,'expired identity cannot be reused');
insert into admission_fixture values('newtoken',public.reserve_planning_request(pg_temp.fixture('p1'),pg_temp.fixture('r1'),'replacement'));
reset role;
select throws_ok($$select * from private.append_planning_revision(pg_temp.fixture('newtoken'),'{}')$$,'22023',null,'trusted writer rejects non-envelope content');
update public.account_memberships set role='member' where user_id='71000000-0000-4000-8000-000000000001';
select throws_ok($$select * from private.append_planning_revision(pg_temp.fixture('newtoken'),'{}')$$,'P0002',null,'revoked ownership invalidates previously issued reservation');
select throws_ok($$select public.reserve_planning_request(pg_temp.fixture('p3'),pg_temp.fixture('r3'),'revoked')$$,'P0002',null,'revoked owner cannot reserve new planning');
update public.account_memberships set role='owner' where user_id='71000000-0000-4000-8000-000000000001';
select private.release_planning_request(pg_temp.fixture('newtoken'));
select throws_ok($$select * from private.append_planning_revision(pg_temp.fixture('newtoken'),'{}')$$,'42501',null,'released reservation cannot authorize write');
update private.planning_requests set completed_at=clock_timestamp();
set local role authenticated;
insert into admission_fixture values('conflict',public.reserve_planning_request(pg_temp.fixture('p3'),pg_temp.fixture('r3'),'conflict'));
select lives_ok($$select * from public.append_product_revision(pg_temp.fixture('p3'),pg_temp.fixture('r3'),'Admission three',null,'{}')$$,'Phase 1 can advance head while generation is in flight');
reset role;
select throws_ok($$select * from private.append_planning_revision(pg_temp.fixture('conflict'),'{"schemaVersion":"planning-envelope/1"}')$$,'40001',null,'reserved writer cannot overwrite a newer Phase 1 revision');
select private.release_planning_request(pg_temp.fixture('conflict'));
update admission_fixture set v=(select current_revision_id from public.products where id=pg_temp.fixture('p3')) where k='r3';
-- Existing product has two attempts, including expired/released attempts.
insert into private.planning_requests(owner_id,product_id,expected_revision_id,request_key,completed_at)
select '71000000-0000-4000-8000-000000000001',pg_temp.fixture('p1'),pg_temp.fixture('r1'),'rate-'||n,clock_timestamp() from generate_series(1,3)n;
set local role authenticated;
select throws_ok($$select public.reserve_planning_request(pg_temp.fixture('p1'),pg_temp.fixture('r1'),'sixth')$$,'53300',null,'expired and released attempts still count toward product rate');
reset role;
insert into private.planning_requests(owner_id,product_id,expected_revision_id,request_key,completed_at)
select '71000000-0000-4000-8000-000000000001',pg_temp.fixture('p2'),pg_temp.fixture('r2'),'owner-rate-'||n,clock_timestamp() from generate_series(1,3)n;
set local role authenticated;
select throws_ok($$select public.reserve_planning_request(pg_temp.fixture('p3'),pg_temp.fixture('r3'),'owner-excess')$$,'53300',null,'owner rate applies across products');
select throws_ok($$select public.reserve_planning_request(pg_temp.fixture('p3'),gen_random_uuid(),'stale')$$,'40001',null,'admission rejects stale head before generation');
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.reserve_planning_request(pg_temp.fixture('p3'),pg_temp.fixture('r3'),'anonymous')$$,'42501',null,'admission requires authentication');
reset role;
select is((select count(*) from public.product_revisions where product_id=pg_temp.fixture('p1')),1::bigint,'failed reservations and writes preserve immutable history');
select * from finish();
rollback;
